// n8n Docker Desktop -> NestJS tren Windows.
// Neu n8n chay truc tiep tren Windows, doi base_url thanh http://127.0.0.1:3001
return {json:{input:$json.body,config:{base_url:'http://host.docker.internal:3001',max_age_seconds:120}}};

const input = $json.input;
const config = $json.config;
const errors = [];
let data = input;
if (typeof data === 'string') {
  try { data = JSON.parse(data); } catch { errors.push('Body không phải JSON hợp lệ.'); }
}
if (!data || typeof data !== 'object' || Array.isArray(data)) {
  errors.push('Body phải là một JSON object.'); data = {};
}
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
for (const key of ['event_id','run_id']) if(typeof data[key] !== 'string' || !uuid.test(data[key])) errors.push(`${key} phải là UUID hợp lệ.`);
if(typeof data.device_id !== 'string' || !data.device_id.trim() || data.device_id.length > 100) errors.push('device_id phải là mã thiết bị hoặc UUID.');
if(!Number.isSafeInteger(data.sequence) || data.sequence < 0) errors.push('sequence phải là số nguyên không âm.');
const ranges = {temperature:[-10,60],humidity:[0,100],light_percent:[0,100],occupancy_count:[0,100],co2_ppm:[300,5000],power_w:[0,20000]};
for(const [key,[min,max]] of Object.entries(ranges)) {
  const v=data[key];
  if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max) errors.push(`${key} phải là số từ ${min} đến ${max}.`);
}
if(!Number.isInteger(data.occupancy_count)) errors.push('occupancy_count phải là số nguyên.');
if(typeof data.door_open!=='boolean') errors.push('door_open phải là boolean.');
const time = typeof data.observed_at==='string' && /^\d{4}-\d\d-\d\dT.*(?:Z|[+-]\d\d:\d\d)$/.test(data.observed_at) ? Date.parse(data.observed_at) : NaN;
if(!Number.isFinite(time)) errors.push('observed_at phải là ISO timestamp có múi giờ.');
else if(time > Date.now()+60000) errors.push('observed_at vượt quá 60 giây trong tương lai.');
for(const key of ['simulated','occupancy']) if(data[key]!==undefined && typeof data[key]!=='boolean') errors.push(`${key} phải là boolean.`);
if(typeof data.occupancy==='boolean' && data.occupancy!==(data.occupancy_count>0)) errors.push('occupancy không khớp occupancy_count.');
for(const key of ['device_code','room','room_code']) if(data[key]!==undefined&&(typeof data[key]!=='string'||!data[key].trim()||data[key].length>100)) errors.push(`${key} không hợp lệ.`);
if(data.schema_version!==undefined && data.schema_version!==2)errors.push('Chỉ hỗ trợ telemetry schema_version 2 (khác với tên workflow V3).');
if(data.light_raw!==undefined && (!Number.isInteger(data.light_raw)||data.light_raw<0||data.light_raw>4095))errors.push('light_raw phải là số nguyên từ 0 đến 4095.');
for(const [key,max] of [['pm25_ug_m3',500],['water_l_min',100]]) if(data[key]!==undefined&&(typeof data[key]!=='number'||!Number.isFinite(data[key])||data[key]<0||data[key]>max)) errors.push(`${key} không hợp lệ.`);
if(data.actual_state!==undefined && (!data.actual_state || typeof data.actual_state!=='object'||Array.isArray(data.actual_state))) errors.push('actual_state phải là object.');
const fields=['device_id','device_code','event_id','run_id','sequence','observed_at','temperature','humidity','light_percent','occupancy_count','co2_ppm','power_w','door_open','simulated','occupancy','room','room_code','light_raw','schema_version','actual_state','pm25_ug_m3','water_l_min'];
const payload=Object.fromEntries(fields.filter(k=>data[k]!==undefined).map(k=>[k,data[k]]));
const raw = input && typeof input==='object'&&!Array.isArray(input) ? input : {received_body:input??null};
return {json:{valid:errors.length===0,errors,telemetry_payload:payload,
 error_record:{device_code:typeof data.device_code==='string'?data.device_code.slice(0,80):typeof data.device_id==='string'?data.device_id.slice(0,80):undefined,reason:errors.join(' | ')||'UNKNOWN_VALIDATION_ERROR',raw_payload:raw},
 max_age_seconds:config.max_age_seconds}};

const response=$json;
const source=$('Validate Telemetry').first().json;
const status=response.statusCode;
const body=response.body;
if(!Number.isInteger(status)) throw new Error('Không nhận được statusCode. Kiểm tra Full Response của Save Telemetry.');
if(status>=200&&status<300){
 if(typeof body?.created!=='boolean'||!body?.telemetry?.id||!body?.telemetry?.raw_payload)throw new Error('Backend response sai contract v2.');
 return {json:{saved:true,created:body.created,telemetry:body.telemetry,max_age_seconds:source.max_age_seconds}};
}
if([400,404,409,422].includes(status)) return {json:{saved:false,error_record:{device_code:source.error_record.device_code,reason:'BACKEND_REJECTED_HTTP_'+status+' | '+JSON.stringify(body),raw_payload:source.telemetry_payload}}};
throw new Error('Backend HTTP '+status+': '+JSON.stringify(body));

const t=$json.telemetry;
const payload=t.raw_payload;
return {json:{...payload,device_id:t.device_id,telemetry_id:t.id,correlation_id:t.event_id,event_id:t.event_id,workflow_version:'V3',ingestion_status:'ACCEPTED_NEW',ready_for_decision:true,occupancy:t.occupancy_count>0,age_seconds:$json.age_seconds,next_step:'Connect flow 02 here when available'}};
